/**
 * Regenerates `public/previews/<host>.jpg`, one per project in `content.json`.
 *
 * Every preview is a static screenshot: the live iframes pulled 40-50 third-party
 * requests into the page and cost the Lighthouse budget of spec 17 (Performance 0.82,
 * Best Practices 0.79 on `/en`). Run this by hand when a client site is redesigned:
 *
 *     bun scripts/capture-previews.ts [host ...]
 *
 * Playwright is already the dev dependency of the E2E suite, so this adds nothing.
 */
import { chromium } from '@playwright/test'

import { content } from '../src/lib/content'

// 16:11, the aspect ratio of the card's `.preview` box. The page lays out at 1440 CSS
// pixels — a desktop, not a squeezed phone — and is written out at two thirds of that,
// which is still ~2.7x the ~360px the card is ever painted at and a third of the bytes.
const VIEWPORT = { width: 1440, height: 990 }
const SCALE = 2 / 3

// Cookie walls make for a useless preview, so the first matching control gets clicked.
// Spanish and English, the two languages these sites ship in.
const CONSENT =
  /^(accept|accept all|allow all|got it|ok|agree|i agree)|(acept|entend|de acuerdo|permitir)/i

const hosts = new Set(content.es.projects.map((project) => project.host))
const only = process.argv.slice(2)

const browser = await chromium.launch()
const page = await browser.newPage({ viewport: VIEWPORT, deviceScaleFactor: SCALE })

for (const project of content.es.projects) {
  if (only.length > 0 && !only.includes(project.host)) continue
  if (!hosts.delete(project.host)) continue

  console.log(`→ ${project.host}`)
  await page.goto(project.url, { waitUntil: 'load', timeout: 60_000 })
  await page.waitForLoadState('networkidle', { timeout: 30_000 }).catch(() => {})

  for (const button of await page.getByRole('button').all()) {
    const label = (await button.textContent().catch(() => ''))?.trim() ?? ''
    if (!CONSENT.test(label)) continue
    await button.click({ timeout: 5_000 }).catch(() => {})
    break
  }

  // Entrance animations are the norm on these sites; a screenshot taken mid-fade is a
  // screenshot of nothing.
  await page.waitForTimeout(4_000)
  // JPEG, not PNG: these are photographic screenshots, where PNG cost 2.5 MB across the
  // six against 723 KB here for the same 960x660 pixels.
  await page.screenshot({ path: `public/previews/${project.host}.jpg`, quality: 82 })
}

await browser.close()

// How each project is previewed. Declarative and keyed by **host**, never by position
// in `content.json`: reordering the list must not put a live iframe on a site that
// answers `X-Frame-Options: DENY`, which is exactly what an index-keyed table would do.
// Header check run on 2026-09-05 (design doc §8).

export type PreviewMode = 'iframe' | 'screenshot'

export const PREVIEWS: Record<string, PreviewMode> = {
  'nera-agro.com': 'iframe',
  'agropro.ag': 'iframe',
  'kodaiverse.com': 'iframe',
  'masushuaia.com': 'iframe',
  // `X-Frame-Options: DENY` + `frame-ancestors 'none'`.
  'creativamedialab.com': 'screenshot',
  // Does not answer `curl` at all (WAF).
  'telecentro.com.ar': 'screenshot',
}

/**
 * A host nobody declared falls back to a screenshot: an undeclared site may well refuse
 * to be framed, and a placeholder is a far cheaper mistake than an empty iframe. The
 * unit test is what keeps a new project in `content.json` from staying undeclared.
 */
export function previewMode(host: string): PreviewMode {
  return PREVIEWS[host] ?? 'screenshot'
}

/**
 * Reveal stagger of the projects grid (`MOTION_SPEC` §9): 90ms per column, restarting
 * on every row, so a card is never held back by the rows above it. Three columns is the
 * widest the grid ever gets at `minmax(min(100%, 300px), 1fr)` inside `container-page`.
 */
export function projectDelay(index: number): number {
  return 90 * (index % 3)
}

import { expect, test } from 'bun:test'

import { Glob } from 'bun'

import { ui } from '../src/lib/ui'

// ── The built site ───────────────────────────────────────────────────────────
// Every other test of this repo reads source. These read `dist/`, because the assertions
// below are the ones no single component can make: they are about what the whole site
// emits once Astro has scoped the styles and Lightning CSS has merged the media queries.
// The build takes well under a second, so it runs here rather than being assumed.

const root = Bun.fileURLToPath(new URL('../', import.meta.url))

const build = Bun.spawnSync(['bun', 'run', 'build'], { cwd: root, stdout: 'pipe', stderr: 'pipe' })
if (build.exitCode !== 0) {
  throw new Error(`astro build failed:\n${build.stderr.toString()}${build.stdout.toString()}`)
}

const pages = {
  '/': await Bun.file(`${root}dist/index.html`).text(),
  '/en': await Bun.file(`${root}dist/en/index.html`).text(),
}

const stylesheets = await Array.fromAsync(new Glob('dist/**/*.css').scan({ cwd: root }))
const css = (await Promise.all(stylesheets.map((file) => Bun.file(root + file).text()))).join('\n')

// ── Reduced motion, whole-site sweep ─────────────────────────────────────────
// The assertion no single block could make. Each section guards its own motion; only the
// built stylesheet can say whether *every* one of them did.

/**
 * Every declaration of the built CSS with the stack of at-rules that encloses it.
 * Minified CSS is one line, so this walks braces instead of matching a shape.
 */
function declarations(styles: string) {
  const found: { declaration: string; selector: string; enclosing: string[] }[] = []
  const stack: string[] = []
  let buffer = ''

  const flush = () => {
    const declaration = buffer.trim()
    buffer = ''
    if (!declaration.includes(':')) return
    const selector = stack.at(-1) ?? ''
    found.push({ declaration, selector, enclosing: [...stack] })
  }

  for (const char of styles) {
    if (char === '{') {
      stack.push(buffer.trim())
      buffer = ''
    } else if (char === '}') {
      flush()
      stack.pop()
    } else if (char === ';') {
      flush()
    } else {
      buffer += char
    }
  }
  return found
}

const built = declarations(css)
const guarded = (enclosing: string[]) =>
  enclosing.some((at) => at.includes('prefers-reduced-motion') && at.includes('no-preference'))

test('every animation in the built CSS sits inside a no-preference block', () => {
  const unguarded = built
    .filter(({ declaration }) => /^animation\s*:/.test(declaration))
    .filter(({ enclosing }) => !guarded(enclosing))
    .map(({ selector, declaration }) => `${selector} { ${declaration} }`)

  expect(unguarded).toEqual([])
})

/** The properties whose transition actually moves something on screen. */
const MOVING =
  /\b(all|transform|translate|rotate|scale|gap|row-gap|column-gap|top|right|bottom|left|inset|width|height|margin|padding)\b/

test('every transition of a moving property sits inside a no-preference block', () => {
  const unguarded = built
    .filter(({ declaration }) => /^transition\s*:/.test(declaration) && MOVING.test(declaration))
    .filter(({ enclosing }) => !guarded(enclosing))
    .map(({ selector, declaration }) => `${selector} { ${declaration} }`)

  expect(unguarded).toEqual([])
})

test('no hover state moves an element outside a no-preference block', () => {
  const unguarded = built
    .filter(({ selector }) => selector.includes(':hover'))
    .filter(({ declaration }) =>
      /^(transform|translate|rotate|scale|gap|row-gap|column-gap)\s*:/.test(declaration),
    )
    .filter(({ enclosing }) => !guarded(enclosing))
    .map(({ selector, declaration }) => `${selector} { ${declaration} }`)

  expect(unguarded).toEqual([])
})

test('every hidden resting state is behind .has-js, so the page reads without JavaScript', () => {
  const hidden = built
    .filter(({ declaration }) => /^opacity\s*:\s*0(\.\d+)?$/.test(declaration))
    .filter(({ selector }) => /\[data-(reveal|boot|word)\]/.test(selector))
    .filter(
      ({ selector, enclosing }) =>
        ![selector, ...enclosing].some((part) => part.includes('has-js')),
    )
    .map(({ selector }) => selector)

  expect(hidden).toEqual([])
})

// ── The focus ring ───────────────────────────────────────────────────────────

test('the global focus ring is :focus-visible, never :focus', () => {
  const ring = built.filter(
    ({ selector, declaration }) =>
      selector.includes(':focus-visible') && /^outline\s*:/.test(declaration),
  )
  expect(ring.length).toBeGreaterThan(0)
  expect(ring.some(({ declaration }) => declaration.includes('var(--color-accent)'))).toBe(true)

  // A bare `:focus` outline would leave a ring behind after a mouse click.
  const bare = built
    .filter(({ selector }) => /:focus(?![\w-])/.test(selector))
    .filter(({ declaration }) => /^outline/.test(declaration))
    .map(({ selector }) => selector)
  expect(bare).toEqual([])
})

test('inside the contact card the ring uses the inverted accent', async () => {
  // The card inverts the theme, so `--color-accent` resolves against a background it was
  // never measured on — the contrast bug of issue 13, in the one place the global rule
  // cannot be right. Asserted on the built CSS, because Astro's scoping is what decides
  // whether the override actually reaches the email and the pills.
  const override = built.find(
    ({ selector, declaration }) =>
      selector.includes('.card') &&
      selector.includes(':focus-visible') &&
      declaration.includes('--color-contact-accent'),
  )
  expect(override?.declaration).toMatch(/^outline-color:/)

  // The duplicate that would drift: the global rule covers the project cards now.
  const projects = await Bun.file(`${root}src/components/Projects.astro`).text()
  expect(projects).not.toContain(':focus-visible')
})

// ── Headings, landmarks and the tab order ────────────────────────────────────

/** The tags of the built HTML, in document order, with their attributes. */
const tags = (html: string, names: string) =>
  [...html.matchAll(new RegExp(`<(${names})\\b([^>]*)>`, 'g'))].map(([, name, attributes]) => ({
    name: name!,
    attributes: attributes!,
  }))

test.each(Object.keys(pages))('%s has exactly one <h1>', (route) => {
  expect(tags(pages[route as keyof typeof pages], 'h1').length).toBe(1)
})

test.each(Object.keys(pages))('%s never skips a heading level', (route) => {
  const levels = tags(pages[route as keyof typeof pages], 'h[1-6]').map(({ name }) =>
    Number(name[1]),
  )
  expect(levels[0]).toBe(1)
  const skips = levels.filter((level, index) => index > 0 && level > levels[index - 1]! + 1)
  expect(skips).toEqual([])
})

test.each(Object.keys(pages))('%s names every section that carries an id', (route) => {
  const unnamed = tags(pages[route as keyof typeof pages], 'section')
    .filter(({ attributes }) => /\sid=/.test(attributes))
    .filter(({ attributes }) => !/aria-label(ledby)?=/.test(attributes))
  expect(unnamed).toEqual([])
})

test.each(Object.keys(pages))('%s keeps every preview iframe out of the tab order', (route) => {
  const frames = tags(pages[route as keyof typeof pages], 'iframe')
  expect(frames.length).toBeGreaterThan(0)
  for (const { attributes } of frames) {
    expect(attributes).toMatch(/aria-hidden="true"/)
    expect(attributes).toMatch(/tabindex="-1"/)
  }
})

test.each(Object.keys(pages))('%s keeps the decorative glyphs out of the tree', (route) => {
  const html = pages[route as keyof typeof pages]
  // The canvas and the marquee clones are covered by `network.test.ts` and
  // `stack.test.ts`; these are the glyphs, which are spread over four components.
  for (const glyph of ['✳', '↗']) {
    for (const match of html.matchAll(new RegExp(`<[^>]*>[^<]*${glyph}`, 'g'))) {
      expect(match[0]).toContain('aria-hidden')
    }
  }
  expect(html).toContain('role="log"')
  expect(html).toContain('aria-live="off"')
})

test.each(Object.entries(pages))(
  '%s makes the skip link the first focusable element',
  (route, html) => {
    const focusable = tags(html, 'a|button|input|select|textarea|iframe').filter(
      ({ attributes }) => !/tabindex="-1"/.test(attributes),
    )
    const first = focusable[0]
    expect(first?.name).toBe('a')
    expect(first?.attributes).toContain('href="#main"')

    const lang = route === '/en' ? 'en' : 'es'
    expect(html).toContain(ui[lang].skipToContent)
    // And the target has to be able to take the focus the link sends it.
    expect(html).toMatch(
      /<main[^>]*id="main"[^>]*tabindex="-1"|<main[^>]*tabindex="-1"[^>]*id="main"/,
    )
  },
)

test('the sticky nav never covers what the keyboard just focused', async () => {
  const app = await Bun.file(`${root}src/styles/app.css`).text()
  // `scroll-margin-top` (issue 08) answers fragment jumps; focus scrolling is the
  // scroll container's own padding, which is a different property.
  expect(app).toMatch(/scroll-padding-top:\s*var\(--nav-h\)/)
})

test.each(Object.entries(pages))('%s reaches its translation without JavaScript', (route, html) => {
  const sibling = route === '/en' ? '/' : '/en'
  const toggle = tags(html, 'a').find(({ attributes }) => attributes.includes('data-lang-toggle'))
  expect(toggle?.attributes).toContain(`href="${sibling}"`)
  expect(toggle?.attributes).toContain('rel="alternate"')
})

import { expect, test } from 'bun:test'

import { content, LANGS } from '../src/lib/content'
import { PREVIEWS, previewMode, projectDelay } from '../src/lib/projects'

/** The hosts that answered a framing check on 2026-09-05 (spec 11, design doc §8). */
const BLOCKED = ['creativamedialab.com', 'telecentro.com.ar']

const hosts = LANGS.flatMap((lang) => content[lang].projects.map((project) => project.host))

test('every project in content.json has a declared preview mode', () => {
  for (const host of hosts) expect(PREVIEWS[host]).toBeDefined()
})

test('the two hosts that block framing are screenshots, the other four are iframes', () => {
  const modes = [...new Set(hosts)].map((host) => [host, previewMode(host)])

  expect(Object.fromEntries(modes)).toEqual({
    'nera-agro.com': 'iframe',
    'agropro.ag': 'iframe',
    'kodaiverse.com': 'iframe',
    'masushuaia.com': 'iframe',
    'creativamedialab.com': 'screenshot',
    'telecentro.com.ar': 'screenshot',
  })
  for (const host of BLOCKED) expect(previewMode(host)).toBe('screenshot')
})

test('the mode is keyed by host, so reordering content.json cannot swap it', () => {
  // The table is read by host, never by position: the reversed list yields the same
  // modes, which is what keeps an iframe off a site that answers `X-Frame-Options`.
  const forward = content.es.projects.map((project) => previewMode(project.host))
  const reversed = [...content.es.projects].reverse().map((project) => previewMode(project.host))

  expect(reversed).toEqual([...forward].reverse())
  expect(Object.keys(PREVIEWS).every((key) => Number.isNaN(Number(key)))).toBe(true)
})

test('a host nobody declared falls back to a screenshot, never to an iframe', () => {
  expect(previewMode('example.com')).toBe('screenshot')
})

test('projectDelay staggers 90ms per column, so each row starts over', () => {
  expect([0, 1, 2, 3, 4, 5].map(projectDelay)).toEqual([0, 90, 180, 0, 90, 180])
})

/**
 * The rest of the block is markup, so what is guarded is the shape of the component:
 * the previews are decoration and must not reach the keyboard, the copy comes from
 * `content.json`, and the shimmer only runs when motion is welcome.
 */
const source = await Bun.file(new URL('../src/components/Projects.astro', import.meta.url)).text()
const [, frontmatter = '', body = ''] = /^---([\s\S]*?)^---([\s\S]*)$/m.exec(source) ?? []
const [, styles = ''] = /<style>([\s\S]*?)<\/style>/.exec(body) ?? []
const markup = body.replace(/<style>[\s\S]*?<\/style>/g, '')
const [, iframe = ''] = /<iframe([\s\S]*?)\/>/.exec(markup) ?? []

test('exactly one iframe is written, and only projects in iframe mode render it', () => {
  expect(markup.match(/<iframe/g)).toHaveLength(1)
  // The screenshot projects mount no iframe at all: the tag sits behind the mode.
  expect(markup).toMatch(/project\.iframe &&[\s\S]*?<iframe/)
})

test('the iframe is lazy, sandboxed and out of the accessibility tree', () => {
  expect(iframe).toMatch(/loading="lazy"/)
  expect(iframe).toMatch(/sandbox/)
  expect(iframe).toMatch(/aria-hidden="true"/)
  expect(iframe).toMatch(/tabindex="-1"/)
  // A tab stop over a decorative preview is the a11y bug this pair guards.
  expect(styles).toMatch(/\.frame \{[^}]*pointer-events: none/)
})

test('the screenshot falls back to the striped placeholder while the files are missing', () => {
  expect(frontmatter).toMatch(/existsSync/)
  expect(frontmatter).toMatch(/previews\/\$\{project\.host\}\.png/)
  expect(markup).toMatch(/project\.shot &&/)
  expect(styles).toMatch(/repeating-linear-gradient/)
})

test('the shimmer runs only under prefers-reduced-motion: no-preference', () => {
  const [, animated = ''] =
    /@media \(prefers-reduced-motion: no-preference\) \{([\s\S]*)/.exec(styles) ?? []
  expect(styles).toMatch(/@media \(prefers-reduced-motion: no-preference\)/)
  expect(animated).toMatch(/animation: shimmer 2\.8s ease-in-out infinite/)
  expect(styles.replace(animated, '')).not.toMatch(/animation:/)
})

test('the reveal sits on the wrapper and the hover transform on the card', () => {
  expect(markup).toMatch(/<li data-reveal data-delay=\{project\.delay\}>/)
  expect(styles).toMatch(/\.card:hover \{[^}]*transform: translateY\(-4px\)/)
})

test('every string comes from content.ts', () => {
  expect(frontmatter).toMatch(/from '\.\.\/lib\/content'/)
  expect(markup).toMatch(/t\.secProjects/)
  expect(markup).toMatch(/t\.projectsTitle/)
  expect(markup).toMatch(/t\.projectsSub/)
  for (const literal of ['Nera', 'PROYECTOS', 'AGTECH', 'nera-agro.com']) {
    expect(markup).not.toContain(literal)
  }
})

// Single source of content: `handoff/content.json` is read-only and must not be
// duplicated, so the import deliberately crosses out of `src/`. Astro inlines it at
// build time, so `dist/` ships no JSON of its own.
//
// Named imports, not a default one: they are what lets Rollup drop the keys a client
// script does not use (see `json.stringify` in astro.config.mjs).
import { consoleLog, i18n, links, stack } from '../../handoff/content.json'

export type Lang = 'es' | 'en'

/** Derived from the JSON on purpose: a new key in content.json needs no type edit. */
export type Content = (typeof i18n)['es']

export const LANGS = ['es', 'en'] as const satisfies readonly Lang[]

/**
 * Identity, not copy: the same in both languages and absent from content.json, which
 * only holds translatable strings. Nav, footer, and <title> all read it from here so
 * the name still lives in exactly one place.
 */
export const site = { name: 'Marcos Arrieta', handle: '@djmaam' } as const

export const content: Record<Lang, Content> = i18n
export { consoleLog, links, stack }

